/** user-defined types **/

/**
 * What a shortcut does.
 */
export type Action =
  "show_hide" | "ask" | "screenshot" | "auto_answer" | "pause_resume" | "switch_skill" | "bookmark";
/**
 * One action item from the summary (PRD MEM-3).
 */
export type ActionItem = {
  id: string;
  text: string;
  owner: string | null;
  due: string | null;
  done: boolean;
};
export type AnswerDone = { requestId: string; usage: Usage; finishReason: FinishReason };
export type AnswerError = { requestId: string; error: SidekickError };
export type AnswerFormat = "cue_then_full" | "full_only";
export type AnswerToken = { requestId: string; delta: string };
/**
 * Basic facts about the running app, shown in the overlay and diagnostics.
 */
export type AppInfo = { name: string; version: string; os: string };
/**
 * One action and its key combination.
 */
export type Binding = { action: Action; keys: string };
/**
 * A moment the user marked (PRD 5 "Bookmarks").
 */
export type Bookmark = { id: string; atMs: number; label: string | null };
/**
 * What to capture.
 */
export type CaptureRequest =
  /**
   * The main display.
   */
  | { mode: "screen" }
  /**
   * One window from `list_windows`.
   */
  | { mode: "window"; windowId: number }
  /**
   * Part of the main display, as fractions of its size.
   */
  | { mode: "region"; region: Region };
/**
 * One turn of the conversation: text, plus optionally one screenshot (PRD SCR-3).
 */
export type ChatMessage = {
  role: Role;
  content: string;
  /**
   * A stored screenshot to show the model with this message. The app
   * loads it from the encrypted database into `image`; pixels never cross IPC.
   */
  screenshotId?: string | null;
};
/**
 * What the user confirmed before listening started (PRD 8, "Session start confirmation").
 */
export type ConsentOption =
  /**
   * Participants are aware of and agree to transcription: mic and system audio.
   */
  | "participants_agreed"
  /**
   * "Transcribe me only": the microphone only, never other participants.
   */
  | "me_only";
/**
 * A document passage with what a citation needs.
 */
export type ContextChunk = {
  chunkId: number;
  documentId: string;
  documentName: string;
  page: number | null;
  text: string;
};
/**
 * How much context to gather (tech doc 13.5: last 3 minutes, top 5 chunks).
 */
export type ContextOptions = { windowMs: number; topK: number };
export type ContextPack = {
  /**
   * The most recent `window_ms` of transcript, in time order.
   */
  transcript: TranscriptLine[];
  /**
   * Rolling notes (filled by T-024).
   */
  notes: string | null;
  /**
   * Best document passages, best first.
   */
  chunks: ContextChunk[];
  /**
   * The latest screenshot from the last 10 minutes, shown to the model
   * with the full answer and cited as a source (PRD SCR-3).
   */
  screenshot: Screenshot | null;
};
export type Diagnostics = {
  appVersion: string;
  os: string;
  protection: ProtectionStatus;
  stages: StageStats[];
};
export type DocStatus = "queued" | "parsing" | "embedding" | "ready" | "failed";
/**
 * A document as the Library shows it.
 */
export type DocumentInfo = {
  id: string;
  name: string;
  status: DocStatus;
  pageCount: number | null;
  chunkCount: number;
  sizeBytes: number;
  error: string | null;
  createdAt: number;
};
/**
 * How hard the model should think. Lower is faster and cheaper.
 */
export type Effort = "low" | "medium" | "high";
/**
 * Stable error codes. The UI decides what to show from the code, never the message.
 */
export type ErrorCode =
  | "CONSENT_REQUIRED"
  | "PERMISSION_DENIED"
  | "KEY_MISSING"
  | "KEY_INVALID"
  | "RATE_LIMITED"
  | "PROVIDER_UNAVAILABLE"
  | "STT_DISCONNECTED"
  | "UNSUPPORTED_FILE"
  | "PARSE_FAILED"
  | "CONTEXT_TOO_LARGE"
  | "CAPTURE_EXCLUSION_UNAVAILABLE"
  | "DB_ERROR"
  | "CANCELLED"
  /**
   * An optimistic version check failed: someone saved first (e.g. `save_notes`).
   */
  | "VERSION_CONFLICT"
  | "INTERNAL";
/**
 * One problem in a Skill file, for the builder and import dialog.
 */
export type FieldError = {
  /**
   * `tools[1]`, `name`, `instructions`, or empty for the whole file.
   */
  field: string;
  message: string;
};
/**
 * Why generation stopped.
 */
export type FinishReason =
  | "end_turn"
  | "max_tokens"
  /**
   * The provider declined to answer; show a neutral notice, not partial text.
   */
  | "refusal"
  | "tool_use"
  | "other";
/**
 * A global shortcut was pressed (`hotkey.pressed`).
 */
export type HotkeyPressed = { action: Action };
/**
 * What an import would add, shown for approval before saving (tech doc 11.5).
 */
export type ImportPreview = {
  skill: Skill;
  /**
   * Tools the Skill asks for; the user approves them by importing.
   */
  requestedTools: Tool[];
  /**
   * A Skill with this id already exists and would be replaced.
   */
  replacesExisting: boolean;
};
/**
 * Document ingest progress (`ingest.progress`).
 */
export type IngestProgress = {
  documentId: string;
  status: DocStatus;
  /**
   * 0–100.
   */
  percent: number;
  error: string | null;
};
/**
 * Result of saving or testing a key.
 */
export type KeyCheck = {
  key: KeyStatus;
  /**
   * True if the provider accepted the key. False means it was saved without
   * a live check because this provider's adapter isn't built yet.
   */
  verified: boolean;
};
/**
 * What the UI may know about a saved key.
 */
export type KeyStatus = {
  saved: boolean;
  /**
   * Last 4 characters, or fewer if the key is shorter. Never more.
   */
  last4: string | null;
};
/**
 * A provider-neutral request.
 */
export type LlmRequest = {
  model: string;
  system: string | null;
  messages: ChatMessage[];
  maxTokens: number;
  effort: Effort | null;
};
/**
 * Whisper model download progress (Settings).
 */
export type ModelDownloadProgress = { name: string; doneBytes: number; totalBytes: number | null };
/**
 * A model the user can pick.
 */
export type ModelInfo = { id: string; displayName: string };
/**
 * An action item to save with a summary.
 */
export type NewActionItem = { text: string; owner: string | null; due: string | null };
/**
 * A finished answer to save.
 */
export type NewAnswer = {
  sessionId: string;
  question: string;
  source: QuestionSource;
  directed: boolean;
  /**
   * The transcript segment the question came from, if detected.
   */
  segmentId: number | null;
  cue: string | null;
  bodyMd: string;
  sources: Source[];
  provider: string;
  model: string;
  latencyMs: number;
  inputTokens: number | null;
  outputTokens: number | null;
};
/**
 * A session's notes. `version` is 0 before the first save.
 */
export type Notes = {
  contentMd: string;
  version: number;
  /**
   * Epoch ms; 0 before the first save.
   */
  updatedAt: number;
  /**
   * Summary and decisions, written when the session ends.
   */
  summaryMd: string | null;
  actionItems: ActionItem[];
};
/**
 * Who the user is, for directed questions and STT boosts (PRD QA-2, LIS-5a).
 */
export type Profile = { name: string; nicknames: string[] };
export type ProtectionState =
  /**
   * The OS hides the overlay from screen sharing and recordings (green shield).
   */
  | "protected"
  /**
   * Exclusion is on, but some capture methods may still see the overlay (amber).
   */
  | "not_guaranteed"
  /**
   * This OS can't hide the overlay (red).
   */
  | "unavailable"
  /**
   * Turned off with `SIDEKICK_DISABLE_EXCLUSION=1` (grey).
   */
  | "disabled";
export type ProtectionStatus = {
  state: ProtectionState;
  /**
   * One sentence for the shield tooltip and Diagnostics.
   */
  reason: string;
};
/**
 * The active provider and model for one kind of service.
 */
export type ProviderChoice = {
  /**
   * Provider id, e.g. `deepgram`, `anthropic`, `openai`.
   */
  provider: string;
  /**
   * Model id, or `None` to use the provider's default.
   */
  model: string | null;
};
/**
 * A catalog entry with the state of its saved key.
 */
export type ProviderEntry = {
  id: string;
  kind: ProviderKind;
  displayName: string;
  keyRequired: boolean;
  implemented: boolean;
  docsUrl: string;
} & { key: KeyStatus };
export type ProviderKind = "stt" | "llm" | "embed" | "search";
/**
 * Where a question came from (`questions.source`).
 */
export type QuestionSource = "detected" | "chat" | "screenshot";
/**
 * Part of the screen, as fractions (0 to 1) of the main display, so the UI
 * can select on a small preview without knowing the display's pixel size.
 */
export type Region = { x: number; y: number; width: number; height: number };
/**
 * How long session data is kept after a session ends (tech doc 4.4).
 */
export type Retention = "session" | "7d" | "30d" | "forever";
/**
 * Who wrote a message.
 */
export type Role = "user" | "assistant";
/**
 * A saved question with its answer, for history (Chat tab, PRD QA-8).
 */
export type SavedAnswer = {
  answerId: string;
  question: string;
  source: QuestionSource;
  directed: boolean;
  cue: string | null;
  bodyMd: string;
  sources: Source[];
  rating: number | null;
  /**
   * Epoch ms.
   */
  createdAt: number;
};
/**
 * A stored screenshot, without its pixels.
 */
export type Screenshot = {
  id: string;
  sessionId: string;
  mimeType: string;
  width: number;
  height: number;
  /**
   * Epoch ms.
   */
  createdAt: number;
};
/**
 * A screenshot was stored (`screenshot.captured`, tech doc 5.2).
 */
export type ScreenshotCaptured = { screenshot: Screenshot };
/**
 * A session as the UI sees it.
 */
export type Session = {
  id: string;
  title: string;
  status: SessionStatus;
  autoAnswer: boolean;
  /**
   * Unix ms.
   */
  createdAt: number;
  startedAt: number | null;
  endedAt: number | null;
  /**
   * The consent recorded for this session, if any.
   */
  consent: ConsentOption | null;
  /**
   * The active Skill, if any (PRD SKL-1).
   */
  skillId: string | null;
};
/**
 * A session was created or changed status (`session.state`).
 */
export type SessionChanged = { session: Session };
/**
 * One page of sessions, newest first.
 */
export type SessionPage = {
  items: Session[];
  /**
   * Pass back to get the next page; `None` on the last page.
   */
  nextCursor: string | null;
};
/**
 * Result of starting a session: the session plus non-fatal warnings to show.
 */
export type SessionStarted = { session: Session; warnings: string[] };
export type SessionStatus = "draft" | "live" | "paused" | "ended";
/**
 * All user settings.
 */
export type Settings = {
  stt: ProviderChoice;
  llm: ProviderChoice;
  embeddings: ProviderChoice;
  /**
   * Web search is optional; `None` means disabled.
   */
  search: ProviderChoice | null;
  autoAnswer: boolean;
  retention: Retention;
  /**
   * Global shortcuts, one per action (tech doc 12.3).
   */
  shortcuts: Binding[];
  profile: Profile;
};
/**
 * A partial update. Only the sections present are replaced; unknown fields are
 * rejected so typos don't silently do nothing.
 */
export type SettingsPatch = {
  stt?: ProviderChoice | null;
  llm?: ProviderChoice | null;
  embeddings?: ProviderChoice | null;
  /**
   * Omit to leave unchanged; `null` disables web search.
   */
  search?: ProviderChoice | null;
  autoAnswer?: boolean | null;
  retention?: Retention | null;
  /**
   * The full set of shortcuts; validated (every action once, no duplicates).
   */
  shortcuts?: Binding[] | null;
  profile?: Profile | null;
};
/**
 * Error returned by every fallible Sidekick function and IPC command.
 *
 * `message` is user-facing and must never contain API keys or meeting content.
 */
export type SidekickError = { code: ErrorCode; message: string; retryable: boolean };
/**
 * A Skill: front matter fields plus the instructions body.
 */
export type Skill = {
  id: string;
  name: string;
  description?: string;
  triggers?: Trigger[];
  tools?: Tool[];
  answerFormat?: AnswerFormat;
  knowledge?: string[];
  instructions: string;
};
/**
 * A saved Skill and whether it's enabled.
 */
export type SkillEntry = {
  id: string;
  name: string;
  description?: string;
  triggers?: Trigger[];
  tools?: Tool[];
  answerFormat?: AnswerFormat;
  knowledge?: string[];
  instructions: string;
} & { enabled: boolean; builtin: boolean };
/**
 * One citation (`answers.sources_json`, tech doc 4.3).
 */
export type Source = {
  /**
   * `doc`, `transcript`, `url` or `screenshot`.
   */
  type: string;
  /**
   * e.g. `<document id>#p14`, `t:754000`, a URL.
   */
  ref: string;
  label: string;
};
/**
 * Measured stages. Targets come from tech doc 10.1 and 13.1.
 */
export type Stage =
  /**
   * End of speech to final segment received.
   */
  | "transcript_lag"
  /**
   * Question end to first cue token.
   */
  | "question_to_cue"
  /**
   * Question end to first full-answer token.
   */
  | "question_to_answer"
  /**
   * Request sent to first token, per LLM call.
   */
  | "llm_first_token"
  /**
   * Context retrieval for one question.
   */
  | "retrieval";
export type StageStats = {
  stage: Stage;
  count: number;
  p50Ms: number | null;
  p95Ms: number | null;
  targetP50Ms: number;
  targetP95Ms: number;
  /**
   * `None` until there are samples.
   */
  healthy: boolean | null;
};
/**
 * Which audio stream a transcript event belongs to.
 */
export type Stream = "mic" | "system";
export type SttState = "connecting" | "live" | "reconnecting" | "failed";
/**
 * STT connection changes (`stt.status`).
 */
export type SttStatusChanged = { sessionId: string; stream: Stream; state: SttState };
/**
 * The tool allowlist (tech doc 11.5). Tool use itself arrives with Agents (T-045).
 */
export type Tool = "doc_search" | "web_search" | "calculator";
/**
 * Everything the Transcript tab needs when it opens (T-014).
 */
export type Transcript = { lines: TranscriptLine[]; bookmarks: Bookmark[] };
/**
 * A saved transcript line, as the UI shows it.
 */
export type TranscriptLine = {
  id: number;
  speakerLabel: string;
  isUser: boolean;
  text: string;
  startMs: number;
  endMs: number;
};
/**
 * Interim text, replaced by the next partial or a segment (`transcript.partial`).
 */
export type TranscriptPartial = { sessionId: string; stream: Stream; text: string };
/**
 * A finalised segment, already saved (`transcript.segment`).
 */
export type TranscriptSegment = {
  sessionId: string;
  id: number;
  speakerLabel: string;
  isUser: boolean;
  text: string;
  startMs: number;
  endMs: number;
};
export type Trigger = "question_detected" | "chat" | "screenshot";
/**
 * Token counts reported by the provider.
 */
export type Usage = { inputTokens: number; outputTokens: number };
/**
 * A model and whether it's on this computer.
 */
export type WhisperModelEntry = {
  /**
   * `tiny.en`, `base`, ...
   */
  name: string;
  sizeMb: number;
  /**
   * English only, or multilingual (Hinglish needs multilingual).
   */
  englishOnly: boolean;
} & { downloaded: boolean };
/**
 * A window the user can pick.
 */
export type WindowInfo = { id: number; appName: string; title: string };

/** tauri-specta globals **/

import { invoke as TAURI_INVOKE, Channel as TAURI_CHANNEL } from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
  listen: (cb: TAURI_API_EVENT.EventCallback<T>) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
  once: (cb: TAURI_API_EVENT.EventCallback<T>) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
  emit: null extends T
    ? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
    : (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> = { status: "ok"; data: T } | { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(mappings: Record<keyof T, string>) {
  return new Proxy(
    {} as unknown as {
      [K in keyof T]: __EventObj__<T[K]> & {
        (handle: __WebviewWindow__): __EventObj__<T[K]>;
      };
    },
    {
      get: (_, event) => {
        const name = mappings[event as keyof T];

        return new Proxy((() => {}) as any, {
          apply: (_, __, [window]: [__WebviewWindow__]) => ({
            listen: (arg: any) => window.listen(name, arg),
            once: (arg: any) => window.once(name, arg),
            emit: (arg: any) => window.emit(name, arg),
          }),
          get: (_, command: keyof __EventObj__<any>) => {
            switch (command) {
              case "listen":
                return (arg: any) => TAURI_API_EVENT.listen(name, arg);
              case "once":
                return (arg: any) => TAURI_API_EVENT.once(name, arg);
              case "emit":
                return (arg: any) => TAURI_API_EVENT.emit(name, arg);
            }
          },
        });
      },
    },
  );
}
